# Pass 1: find each pair's anomalous ("-pos") start_time, keyed by its "<id>-<channel>-<occurrence>"
# pair key, so its paired "-neg" nominal window can be judged by the same reference date.
anomalous_start_by_pair: dict[str, int] = {}
for record in dataset.records:
    if record.record_id.endswith("-pos") and record.start_time is not None:
        pair_key = record.record_id.removesuffix("-pos")
        anomalous_start_by_pair[pair_key] = record.start_time

train_rows, val_rows, test_rows = [], [], []
for record in dataset.records:
    task = tasks_by_record.get(record.record_id)
    if task is None:
        continue
    row = {
        "record_id": record.record_id,
        "values": record.time_series[0].to_numpy().tolist(),
        "channel": _annotation(record, "channel"),
        "label": _annotation(record, "label"),
        "answer": task.target,
    }
    split = _annotation(record, "split")
    if split == "test":
        test_rows.append(row)
        continue
    pair_key = record.record_id.removesuffix("-pos").removesuffix("-neg")
    reference_start = anomalous_start_by_pair.get(pair_key, record.start_time)
    if reference_start is not None and reference_start >= _VALIDATION_SPLIT_AT_US:
        val_rows.append(row)
    else:
        train_rows.append(row)

return (
    Dataset.from_list(train_rows),
    Dataset.from_list(val_rows),
    Dataset.from_list(test_rows),
)

